package com.bank.limit;

class LimitService {
    static final int DEFAULT_LIMIT = 50000; // primitive int default

    // TRAP: Integer branch + int branch → whole expression is int →
    // when override is null and selected, unboxing null throws NPE.
    int displayLimitBuggy(Customer c) {
        Integer override = c.getCreditLimitOverride();
        // result type = int (because DEFAULT_LIMIT is int) → override is unboxed
        return (override != null) ? override : DEFAULT_LIMIT; // looks safe but...
    }

    // Reproduce the pure trap without a guard, to show the throw explicitly.
    int pureTrap(Integer override) {
        boolean someCondition = true; // selects the override branch
        return someCondition ? override : 0; // null override → NPE on unboxing
    }

    // FIX 1: keep BOTH branches boxed → result is Integer → no unboxing.
    Integer displayLimitBoxed(Customer c) {
        Integer override = c.getCreditLimitOverride();
        return (override != null) ? override : Integer.valueOf(DEFAULT_LIMIT);
    }

    // FIX 2: guard the null BEFORE any unboxing (clear if-style logic).
    int displayLimitGuarded(Customer c) {
        Integer override = c.getCreditLimitOverride();
        if (override == null) {
            return DEFAULT_LIMIT;
        }
        return override; // safe unbox: known non-null
    }
}
