package com.bank.limit;

import java.util.logging.*;

public class TernaryDemo {
    private static final Logger log = Logger.getLogger(TernaryDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        LimitService svc = new LimitService();

        Customer withOverride = new Customer("SAV2001", 200000);
        Customer noOverride = new Customer("CUR3001", null);

        // Guarded buggy method is actually safe because it checks != null first.
        log.info(() -> "Guarded ternary, override present: " + svc.displayLimitBuggy(withOverride));
        log.info(() -> "Guarded ternary, no override: " + svc.displayLimitBuggy(noOverride));

        // The PURE trap: Integer branch selected while null → NPE on unboxing.
        try {
            int limit = svc.pureTrap(null); // condition true → unbox null → throw
            log.info(() -> "unexpected " + limit);
        } catch (NullPointerException e) {
            log.log(Level.SEVERE, "Ternary unboxed a null Integer branch to int", e);
        }

        // Contrast: a plain reference assignment of the SAME null is safe.
        Integer safeAssign = null; // no unboxing, no exception
        log.info(() -> "Plain assignment of null Integer is safe: " + (safeAssign == null));

        // FIX 1: both branches boxed → Integer result, no unbox.
        Integer boxed = svc.displayLimitBoxed(noOverride);
        log.info(() -> "Fix 1 (both boxed): " + boxed);

        // FIX 2: guard before unboxing.
        int guarded = svc.displayLimitGuarded(noOverride);
        log.info(() -> "Fix 2 (guarded): " + guarded);
    }
}

